/**
 * sitemap.xml for nooni.dk — generated by Next.js at build time.
 *
 * Product handles are confirmed against the live Shopify Storefront
 * API. When a new product is published, add its handle to PRODUCT_HANDLES
 * below. We don't fetch the product list at build time because the
 * sitemap should be predictable and reviewable in version control.
 *
 * The dev `nooni_test_product` is intentionally excluded — it shouldn't
 * be indexed.
 *
 * Docs: https://nextjs.org/docs/app/api-reference/file-conventions/metadata/sitemap
 */

import type { MetadataRoute } from "next";

const BASE_URL = "https://nooni.dk";

const PRODUCT_HANDLES = [
  "dots-5stk",
  "dots-med-navn-3stk",
  "loops",
  "emblem",
  "deks-single",
  "deks-duo",
  "tic-tac-take",
];

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();

  return [
    {
      url: `${BASE_URL}/`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 1,
    },
    {
      url: `${BASE_URL}/om-os`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.6,
    },
    ...PRODUCT_HANDLES.map((handle) => ({
      url: `${BASE_URL}/produkter/${handle}`,
      lastModified: now,
      changeFrequency: "monthly" as const,
      priority: 0.8,
    })),
  ];
}
